// lab/prototypes/cellab/palettes.mjs - colour palettes from CelLab (Rudy Rucker & John Walker, Fourmilab, public domain:
// https://www.fourmilab.ch/cellab/), decoded from the dev kit's binary .jcc files (VGA 0-63 intensities scaled to 0-255,
// as WebCA's palette.js does). Each is 256 RGB triples, base64. Generated; do not edit by hand.
export const PALETTES = {
  default: '',
  zhabo: '',
  faders: '',
  brailife: '',
  pond: '',
  perfume: '',
  aurora: '',
  sublime: '',
  rainbow: '',
  autocad: '',
  ranch: '',
  gyre: '',
  dendrite: '',
  bob: '',
  rat: '',
  x29: '',
  fullearth: '',
  xtc: '',
  votedna: '',
  turmite: '',
  steapot: '',
  bleach: '',
  stripe: '',
  openplan: '',
};
// a palette as a 256x1 RGBA byte array (for a texture)
export function paletteRGBA(name) {
  const b = atob(PALETTES[name] || PALETTES.default), o = new Uint8Array(1024);
  for (let i = 0; i < 256; i++) { o[4 * i] = b.charCodeAt(3 * i); o[4 * i + 1] = b.charCodeAt(3 * i + 1); o[4 * i + 2] = b.charCodeAt(3 * i + 2); o[4 * i + 3] = 255; }
  return o;
}

// Gradient palettes for ON's body (not CelLab's): indexed by a cell's activity (0 rest .. 1 firing) instead of its raw
// state, so rules with few states still use the whole ramp.
const STOPS = {
  'on-gold': [[0, 10, 8, 6], [0.25, 70, 42, 18], [0.55, 190, 130, 50], [0.8, 245, 205, 120], [1, 255, 248, 225]],
  'on-ice': [[0, 6, 10, 18], [0.3, 20, 60, 110], [0.6, 60, 160, 210], [0.85, 170, 230, 245], [1, 245, 252, 255]],
  'on-ember': [[0, 8, 4, 4], [0.3, 90, 14, 10], [0.55, 210, 60, 20], [0.8, 255, 160, 50], [1, 255, 240, 190]],
  'on-moss': [[0, 6, 10, 8], [0.3, 24, 60, 40], [0.6, 90, 150, 80], [0.85, 200, 220, 140], [1, 250, 250, 225]],
  'on-violet': [[0, 8, 6, 14], [0.3, 50, 20, 90], [0.6, 150, 60, 190], [0.85, 240, 150, 220], [1, 255, 240, 250]],
};
export const GRADIENTS = Object.keys(STOPS);
export const isGradient = (name) => name in STOPS;
export function gradientRGBA(name) {
  const st = STOPS[name], o = new Uint8Array(1024);
  for (let i = 0; i < 256; i++) {
    const x = i / 255; let k = 0; while (k < st.length - 2 && x > st[k + 1][0]) k++;
    const [x0, ...a] = st[k], [x1, ...b] = st[k + 1], f = Math.min(1, Math.max(0, (x - x0) / (x1 - x0)));
    for (let c = 0; c < 3; c++) o[4 * i + c] = Math.round(a[c] + (b[c] - a[c]) * f);
    o[4 * i + 3] = 255;
  }
  return o;
}
